#include <bits/stdc++.h>
using namespace std;

int bin_pow(int base, int exp, int mod) {
    int res = 1;
    while (exp > 0) {
        if (exp & 1) res = (long long)res * base % mod;
        base = (long long)base * base % mod;
        exp >>= 1;
    }
    return res;
}

const int MAXN = 300005;
unsigned long long dp_array[27][MAXN];
int factorials[MAXN], inv_factorials[MAXN];

int get_perm(int n, int m, int mod) {
    return (long long)factorials[n] * inv_factorials[n - m] % mod;
}

int main() {
    int n, K, MOD;
    scanf("%d %d %d", &n, &K, &MOD);
    if (n % 2 != 0) {
        printf("%d\n", bin_pow(K, n, MOD));
        return 0;
    }
    factorials[0] = 1;
    for (int i = 1; i <= n; ++i) {
        factorials[i] = (long long)factorials[i - 1] * i % MOD;
    }
    inv_factorials[n] = bin_pow(factorials[n], MOD - 2, MOD);
    for (int i = n - 1; i >= 0; --i) {
        inv_factorials[i] = (long long)inv_factorials[i + 1] * (i + 1) % MOD;
    }
    dp_array[0][0] = 1ULL;
    for (int k = 0; k < K; ++k) {
        for (int i = 1; i <= n; ++i) {
            if ((i & n) != i) continue;
            int block_mask = 1 << (31 - __builtin_clz(i));
            unsigned long long &res = dp_array[k + 1][i];
            res = 0ULL;
            for (int j = i - block_mask; j >= 0; j = (j - 1) & i) {
                int j_plus = j + block_mask;
                res += dp_array[k][i ^ j_plus] * inv_factorials[j_plus];
                if (++cnt == 17) {
                    res %= MOD;
                    cnt = 0;
                }
                if (j == 0) break;
            }
            res %= MOD;
        }
    }
    int total_answ = 0;
    for (int i = 0; i <= K; ++i) {
        total_answ = (total_answ + (long long)factorials[n] * dp_array[i][n] % MOD * get_perm(K, i, MOD)) % MOD;
    }
    printf("%d\n", (bin_pow(K, n, MOD) + MOD - total_answ) % MOD);
}
